diff --git a/internal/server/routes_sharing.go b/internal/server/routes_sharing.go
new file mode 100644
index 0000000..95bbbc4
--- /dev/null
+++ b/internal/server/routes_sharing.go
@@ -0,0 +1,114 @@
+package server
+
+import (
+	"embed"
+	"html/template"
+	"net/http"
+	"strconv"
+
+	"git.aisoftwarefactory.world/notes/notes/internal/store"
+)
+
+//go:embed templates/*.html
+var shareTemplates embed.FS
+
+// sharedNoteTemplate renders a note as the read-only page a share link serves.
+var sharedNoteTemplate = template.Must(template.ParseFS(shareTemplates, "templates/shared_note.html"))
+
+// shareTokenLen is how many URL-safe characters a share token carries.
+const shareTokenLen = 22
+
+// shareJSON answers a created link: its id, so it can be revoked, and the
+// path a reader opens.
+type shareJSON struct {
+	ID    int64  `json:"id"`
+	Token string `json:"token"`
+	URL   string `json:"url"`
+}
+
+// registerSharing puts the owner's share endpoints and the public page on
+// the mux. /s/ sits outside /api/, so no session guards it.
+func (s *server) registerSharing(mux *http.ServeMux) {
+	mux.HandleFunc("POST /api/notes/{id}/share", s.createShare)
+	mux.HandleFunc("DELETE /api/notes/{id}/share/{shareId}", s.revokeShare)
+	mux.HandleFunc("GET /s/{token}", s.sharedNote)
+}
+
+func (s *server) createShare(w http.ResponseWriter, r *http.Request) {
+	userID, ok := s.userOf(r)
+	if !ok {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
+		return
+	}
+	noteID, ok := noteIDFrom(w, r)
+	if !ok {
+		return
+	}
+	// Only the owner reaches this point for their own note; another user's
+	// id answers 404, as every other route promises.
+	if _, err := s.store.GetNote(noteID, userID); err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	token, err := store.NewToken(shareTokenLen)
+	if err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	share, err := s.store.CreateShare(noteID, userID, token)
+	if err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	writeJSON(w, http.StatusCreated, shareJSON{
+		ID:    share.ID,
+		Token: share.Token,
+		URL:   "/s/" + share.Token,
+	})
+}
+
+// revokeShare closes one of the caller's links. The {shareId} in the path is
+// the id POST /api/notes/<id>/share answered; a link that is not the
+// caller's, not theirs to close or already closed answers 404.
+func (s *server) revokeShare(w http.ResponseWriter, r *http.Request) {
+	userID, ok := s.userOf(r)
+	if !ok {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
+		return
+	}
+	shareID, err := strconv.ParseInt(r.PathValue("shareId"), 10, 64)
+	if err != nil || shareID < 1 {
+		writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found"})
+		return
+	}
+	if err := s.store.RevokeShare(shareID, userID); err != nil {
+		writeStoreError(w, err)
+		return
+	}
+	w.WriteHeader(http.StatusNoContent)
+}
+
+// sharedNotePage is what the template gets.
+type sharedNotePage struct {
+	Title string
+	Body  string
+}
+
+// sharedNote serves a note to anyone holding its token, no login asked for.
+func (s *server) sharedNote(w http.ResponseWriter, r *http.Request) {
+	token := r.PathValue("token")
+	note, err := s.store.GetShare(token)
+	if err != nil {
+		writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found"})
+		return
+	}
+	w.Header().Set("Content-Type", "text/html; charset=utf-8")
+	w.Header().Set("Cache-Control", "no-store")
+	w.WriteHeader(http.StatusOK)
+	if err := sharedNoteTemplate.Execute(w, sharedNotePage{
+		Title: note.Title,
+		Body:  note.Body,
+	}); err != nil {
+		return
+	}
+}
