+package server_test
+
+import (
+	"bytes"
+	"encoding/json"
+	"io"
+	"net/http"
+	"net/http/httptest"
+	"regexp"
+	"strconv"
+	"strings"
+	"testing"
+
+	"git.aisoftwarefactory.world/notes/notes/internal/server"
+)
+
+// tokenPattern is what a share link's token must be: 22 characters of the
+// URL-safe base64 alphabet.
+var tokenPattern = regexp.MustCompile(`^[A-Za-z0-9_-]{22}$`)
+
+// newNote creates a note for a logged-in user and answers its id.
+func newNote(t *testing.T, srvURL string, auth func(method, path string, body any) *http.Request, title, body string) int64 {
+	t.Helper()
+	status, answer := do(t, auth(http.MethodPost, srvURL+"/api/notes", map[string]any{
+		"title": title,
+		"body":  body,
+	}))
+	if status != http.StatusCreated {
+		t.Fatalf("POST /api/notes: %d %q, want 201", status, answer)
+	}
+	return decodeNote(t, answer).ID
+}
+
+// createShare opens a share link for a note as its owner and answers its id,
+// token and public path.
+func createShare(t *testing.T, srvURL string, auth func(method, path string, body any) *http.Request, noteID int64) (int64, string) {
+	t.Helper()
+	status, body := do(t, auth(http.MethodPost, srvURL+"/api/notes/"+strconv.FormatInt(noteID, 10)+"/share", nil))
+	if status != http.StatusCreated {
+		t.Fatalf("POST /api/notes/%d/share: %d %q, want 201", noteID, status, body)
+	}
+	share := struct {
+		ID    int64  `json:"id"`
+		Token string `json:"token"`
+		URL   string `json:"url"`
+	}{}
+	if err := json.Unmarshal(body, &share); err != nil {
+		t.Fatalf("the share answer is no JSON: %q: %v", body, err)
+	}
+	if !tokenPattern.MatchString(share.Token) {
+		t.Errorf("the share token %q is not 22 URL-safe characters", share.Token)
+	}
+	if share.URL != "/s/"+share.Token {
+		t.Errorf("the share url is %q, want %q", share.URL, "/s/"+share.Token)
+	}
+	if share.ID < 1 {
+		t.Errorf("the share id is %d, want a positive number", share.ID)
+	}
+	return share.ID, share.Token
+}
+
+// getWithoutCookie fetches a path with a client that holds no cookie jar.
+func getWithoutCookie(t *testing.T, url string) (*http.Response, []byte) {
+	t.Helper()
+	client := &http.Client{Jar: nil}
+	res, err := client.Get(url)
+	if err != nil {
+		t.Fatalf("GET %s: %v", url, err)
+	}
+	defer func() { _ = res.Body.Close() }()
+	body, err := io.ReadAll(res.Body)
+	if err != nil {
+		t.Fatalf("read the body of GET %s: %v", url, err)
+	}
+	return res, body
+}
+
+// noAuth answers a request builder that carries no session at all.
+func noAuth() func(method, path string, body any) *http.Request {
+	return func(method, path string, body any) *http.Request {
+		var r io.Reader
+		if body != nil {
+			data, err := json.Marshal(body)
+			if err != nil {
+				panic(err)
+			}
+			r = bytes.NewReader(data)
+		}
+		req, err := http.NewRequest(method, path, r)
+		if err != nil {
+			panic(err)
+		}
+		if body != nil {
+			req.Header.Set("Content-Type", "application/json")
+		}
+		return req
+	}
+}
+
+// TestShareLink is acceptance item A8 in its first half: GET /s/<token>
+// answers a page holding the note's title, without a cookie sent along.
+func TestShareLink(t *testing.T) {
+	st := newStore(t)
+	srv := httptest.NewServer(server.New(server.Config{Store: st}))
+	defer srv.Close()
+	ada := login(t, st, "ada")
+
+	noteID := newNote(t, srv.URL, ada, "Shared Shopping List", "apples and pears")
+	_, token := createShare(t, srv.URL, ada, noteID)
+
+	res, body := getWithoutCookie(t, srv.URL+"/s/"+token)
+	if res.StatusCode != http.StatusOK {
+		t.Fatalf("GET /s/%s without a cookie: %d %q, want 200", token, res.StatusCode, body)
+	}
+	page := string(body)
+	if !strings.Contains(page, "Shared Shopping List") {
+		t.Errorf("the shared page does not hold the note's title: %q", page)
+	}
+	if !strings.Contains(page, "apples and pears") {
+		t.Errorf("the shared page does not hold the note's body: %q", page)
+	}
+	if ct := res.Header.Get("Content-Type"); !strings.HasPrefix(ct, "text/html") {
+		t.Errorf("the shared page answers %q,
